-- New Leaf Hearing Care: add the ReSound Sensia section (insert only) to /resound-hearing-aids/
-- Applies only if the stored page is still exactly what was reviewed.
UPDATE ec_hearing_aids SET content='[{"_type":"block","_key":"k2z0","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k2yz","text":"ReSound Hearing Aids Available In Colorado","marks":[]}]},{"_type":"block","_key":"k2z2","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2z1","text":"These are the hearing aid models available from ReSound.","marks":[]}]},{"_type":"block","_key":"rss000","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"rss001","text":"ReSound Sensia","marks":[]}]},{"_type":"block","_key":"rss002","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"rss003","text":"ReSound Sensia is ReSound''s newest premium hearing aid family. It was released in August 2026 and built on GN''s new AI platform. Its Intelligent All-Around technology combines a real-time sound classifier, a 4-microphone beamformer, and Deep Neural Network noise reduction to lift the voice you want to hear, not just the loudest one in the room. It works automatically, and wearers can focus on a speaker simply by facing them.","marks":[]}]},{"_type":"block","_key":"rss004","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"rss005","text":"Sensia comes in microRIE, RIE, and custom in-ear styles, including rechargeable options. A Bimodal version works with Cochlear™ Nucleus® implant sound processors. ReSound calls Sensia the ","marks":[]},{"_type":"span","_key":"rss006","text":"world''s smallest AI hearing aid","marks":["strong"]},{"_type":"span","_key":"rss007","text":".","marks":[]}]},{"_type":"block","_key":"rss008","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"rss009","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"rss00a","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"rss00b","text":"AcoustIQ™ classifies the sound environment in real time with 88% greater accuracy than the closest premium competitor, so features switch on exactly when they''re needed.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"rss00c","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"rss00d","text":"DNN noise reduction is 17x more efficient than other AI hearing solutions, giving up to 24 hours of battery life in rechargeable styles even with DNN running automatically.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"rss00e","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"rss00f","text":"Independent testing at Hörzentrum Oldenburg showed Sensia delivers the best audibility of the intended speaker rather than the loudest voice in the room.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"k2z4","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2z3","text":"ReSound Enzo IA","marks":[]}]},{"_type":"block","_key":"k2z6","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2z5","text":"The ReSound Enzo IA is designed for severe to profound hearing loss. It is the world’s smallest rechargeable Super Power hearing aid and the first of its kind to support Bluetooth LE Audio and Auracast broadcast streaming.","marks":[]}]},{"_type":"block","_key":"k2z8","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2z7","text":"With a stylish, durable design, the ReSound Enzo IA is built for the most challenging listening situations. It offers exceptional clarity, feedback control, and all-day battery life.","marks":[]}]},{"_type":"block","_key":"k2za","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2z9","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k2zc","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2zb","text":"Clear Focus: Automatically reduces background noise while highlighting speech.","marks":[]}]},{"_type":"block","_key":"k2ze","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2zd","text":"360 All-Around listening: Naturally shifts attention between voices and surrounding sounds.","marks":[]}]},{"_type":"block","_key":"k2zg","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2zf","text":"Comfortable and weatherproof: Lightweight, all-day wear with protective nanocoating.","marks":[]}]},{"_type":"block","_key":"k2zi","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2zh","text":"Flexible connectivity: Supports Bluetooth® LE Audio, Auracast™, and direct streaming from multiple devices.","marks":[]}]},{"_type":"block","_key":"k2zk","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2zj","text":"ReSound Vivia","marks":[]}]},{"_type":"block","_key":"k2zm","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2zl","text":"ReSound Vivia™ is a smart hearing aid that helps you hear better and enjoy the sounds around you. It uses Intelligence Augmented (IA), which works with your brain to make hearing easier. Whether you are in a noisy place or a quiet room, ReSound Vivia helps you hear clearly and stay focused on what you want to hear.","marks":[]}]},{"_type":"block","_key":"k2zo","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2zn","text":"ReSound Vivia™ also features advanced noise reduction and speech enhancement, allowing you to focus on conversations even in challenging listening environments. Its adaptive technology continuously adjusts to your surroundings, ensuring a natural and immersive hearing experience. Designed for all-day comfort, ReSound Vivia™ provides reliable performance, so you can stay connected and engaged in every moment without distraction.","marks":[]}]},{"_type":"block","_key":"k2zq","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2zp","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k2zs","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2zr","text":"Bluetooth Connectivity: ReSound Nexia connects to the new Bluetooth LE Audio, providing the purest sound quality and minimal battery usage for continuous streaming.","marks":[]}]},{"_type":"block","_key":"k2zu","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2zt","text":"Auracast Broadcast Audio: A new Bluetooth technology that allows audio streaming from public places to your hearing aids.","marks":[]}]},{"_type":"block","_key":"k2zw","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2zv","text":"App / Remote Help: ReSound Smart 3D app allows patients to take matters into their own hands by providing: quick buttons, custom programs, remote fine-tuning, and tinnitus management. ReSound Assist gives you live Assistance for face-to-face video appointments from the comfort of your home.","marks":[]}]},{"_type":"block","_key":"k2zy","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2zx","text":"ReSound Savi","marks":[]}]},{"_type":"block","_key":"k300","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2zz","text":"ReSound Savi™ is a smart hearing aid that helps you hear clearly and stay connected every day. It combines the best sound technology with small, comfortable designs and easy Bluetooth® connections. ReSound Savi is made to give you natural sound, all-day comfort, and a simple way to hear better in any situation.","marks":[]}]},{"_type":"block","_key":"k302","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k301","text":"ReSound Savi™ automatically adapts to different environments, reducing background noise and enhancing speech clarity so you can focus on the sounds that matter most. Whether you’re in a bustling café, a quiet park, or on an important phone call, its advanced technology ensures a smooth and effortless listening experience. With long-lasting battery life and a user-friendly design, ReSound Savi™ makes hearing easier, keeping you connected and confident throughout your day.","marks":[]}]},{"_type":"block","_key":"k304","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k303","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k306","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k305","text":"All-Day Power: Keeps going all day, even when streaming music or calls.","marks":[]}]},{"_type":"block","_key":"k308","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k307","text":"Weatherproof: Special coating protects the hearing aids from water and dust.","marks":[]}]},{"_type":"block","_key":"k30a","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k309","text":"Bluetooth and Auracast™: Connects to phones, TVs, and other devices with the newest Bluetooth technology.","marks":[]}]},{"_type":"block","_key":"k30c","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k30b","text":"Auracast Assistant: Use the app to easily connect to public broadcasts like in theaters or airports.","marks":[]}]},{"_type":"block","_key":"k30e","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k30d","text":"Hands-Free Calls: Pick up calls with a tap and talk without holding your phone. Works with iPhones, iPads, and some Android phones.","marks":[]}]},{"_type":"block","_key":"k30g","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k30f","text":"ReSound Nexia","marks":[]}]},{"_type":"block","_key":"k30i","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k30h","text":"ReSound Nexia is an advanced hearing system powered by Organic Hearing™, providing a natural sound experience and seamless connectivity. With ReSound Nexia, users can stream hands-free calls from iPhone, iPad, and compatible Android™ devices directly to their hearing aids. Additionally, these hearing aids can function as a headset, allowing users to stream audio from Mac computers for online meetings or FaceTime calls.","marks":[]}]},{"_type":"block","_key":"k30k","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k30j","text":"For individuals with single-sided deafness, ReSound Nexia offers a wireless ‘CROS’ solution, delivering full sound clarity and matching the microRIE style for a comfortable fit. This comprehensive system enhances daily life by providing clear and natural sound quality, effortless connectivity, and personalized solutions for users with varying hearing needs.","marks":[]}]},{"_type":"block","_key":"k30m","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k30l","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k30o","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k30n","text":"Bluetooth Connectivity: ReSound Nexia connects to the new Bluetooth LE Audio, providing the purest sound quality and minimal battery usage for continuous streaming.","marks":[]}]},{"_type":"block","_key":"k30q","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k30p","text":"Auracast Broadcast Audio: A new Bluetooth technology that allows audio streaming from public places to your hearing aids.","marks":[]}]},{"_type":"block","_key":"k30s","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k30r","text":"App / Remote Help: ReSound Smart 3D app allows patients to take matters into their own hands by providing quick buttons, custom programs, remote fine-tuning, and tinnitus management. ReSound Assist gives you live Assistance for face-to-face video appointments from the comfort of your home.","marks":[]}]},{"_type":"block","_key":"k30u","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k30t","text":"ReSound Omnia RIE & mini RIE","marks":[]}]},{"_type":"block","_key":"k30w","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k30v","text":"ReSound’s newest Omnia hearing aid products operate on the foundation of their Organic Hearing technology. The core principles behind Organic Hearing include natural sound, natural fit, and natural connection to the world. ReSound crafted the perfect balance of nature and science in designing hearing solutions meant to fit your life organically.","marks":[]}]},{"_type":"block","_key":"k30y","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k30x","text":"ReSound Omnia receiver-in-the-ear (RIE) is currently available in two styles: a RIE or mini RIE. These devices are appropriate for fitting mild-to-severe hearing losses. They offer either rechargeable or disposable battery options. Their rechargeable solutions have proven to provide all-day battery power on one charge – even when streaming 100% of the time. This gives you confidence that your hearing aids will perform when you need them.","marks":[]}]},{"_type":"block","_key":"k310","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k30z","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k312","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k311","text":"Bluetooth Connectivity: ReSound OMNIA is made for iPhone and iPad and works with Android devices. Stream hands-free calls for iPhone and iPad. You can also connect to various wireless accessories.","marks":[]}]},{"_type":"block","_key":"k314","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k313","text":"Fitting Assistance: Check My Fit assistance allows you to check if you are wearing your hearing aids correctly. This helps ensure a proper fit for optimal sound quality.","marks":[]}]},{"_type":"block","_key":"k316","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k315","text":"App / Remote Help: ReSound Smart 3D app allows patients to take matters into their own hands by providing quick buttons, custom programs, remote fine-tuning, and tinnitus management. ReSound Assist gives you live Assistance for face-to-face video appointments from the comfort of your home.","marks":[]}]},{"_type":"block","_key":"k318","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k317","text":"Tinnitus Relief: ReSound Relief is one of the most useful hearing aid apps on the market for relieving and managing tinnitus. The app offers a combination of sound therapy, relaxing exercises, meditation, and guidance. The options are endless, as it allows you to layer up to five different sounds to create a soundscape to ease your tinnitus.","marks":[]}]},{"_type":"block","_key":"k31a","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k319","text":"ReSound Omnia ITE","marks":[]}]},{"_type":"block","_key":"k31c","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k31b","text":"ReSound’s Omnia family of hearing aids also offers custom in-the-ear (ITE) devices that are designed to fit your unique ear anatomy. This allows you to enjoy all the benefits of modern hearing aid technology in a smaller package. One of the benefits of choosing a custom device is that it is naturally shielded from wind noise, as they sit inside the ear canal. Additionally, ITE devices do not interfere with glasses or other items worn behind the ears.","marks":[]}]},{"_type":"block","_key":"k31e","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k31d","text":"ReSound Omnia in-the-ear (ITE) products are currently available in a variety of sizes to meet your unique fitting preferences. The types of custom ITE products include: in-the-canal (ITC), completely-in-the-canal (CIC), and invisible-in-the-canal (IIC). These devices are appropriate for fitting mild to severe-to-profound hearing losses. They offer either rechargeable or disposable battery options.","marks":[]}]},{"_type":"block","_key":"k31g","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k31f","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k31i","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k31h","text":"Bluetooth Connectivity: ReSound OMNIA is made for iPhone and iPad and works with Android devices. Stream hands-free calls for iPhone and iPad. You can also connect to various wireless accessories.","marks":[]}]},{"_type":"block","_key":"k31k","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k31j","text":"Fitting Assistance: Check My Fit assistance allows you to check if you are wearing your hearing aids correctly. This helps ensure a proper fit for optimal sound quality.","marks":[]}]},{"_type":"block","_key":"k31m","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k31l","text":"App / Remote Help: ReSound Smart 3D app allows patients to take matters into their own hands by providing quick buttons, custom programs, remote fine-tuning, and tinnitus management. ReSound Assist gives you live Assistance for face-to-face video appointments from the comfort of your home.","marks":[]}]},{"_type":"block","_key":"k31o","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k31n","text":"Tinnitus Relief: ReSound Relief is one of the most useful hearing aid apps on the market for relieving and managing tinnitus. The app offers a combination of sound therapy, relaxing exercises, meditation, and guidance. The options are endless, as it allows you to layer up to five different sounds to create a soundscape to ease your tinnitus.","marks":[]}]},{"_type":"block","_key":"k31q","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k31p","text":"ReSound Omnia BTE & Power BTE","marks":[]}]},{"_type":"block","_key":"k31s","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k31r","text":"The traditional behind-the-ear (BTE) style is also available in the Omnia family. For individuals with significant hearing loss, listening to noise can be extremely difficult. Thankfully, ReSound OMNIA offers the only beamforming in the industry to improve hearing in noise without feeling like volume is compromised.  Their studies revealed that this translated into an incredible 150% improvement in speech understanding of noise.","marks":[]}]},{"_type":"block","_key":"k31u","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k31t","text":"ReSound Omnia BTE and Power BTE are currently available in a BTE style. These devices are appropriate for fitting mild to severe-to-profound hearing losses. They both offer a rechargeable battery solution.","marks":[]}]},{"_type":"block","_key":"k31w","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k31v","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k31y","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k31x","text":"Bluetooth Connectivity: ReSound OMNIA is made for iPhone and iPad and works with Android devices. Stream hands-free calls for iPhone and iPad. You can also connect to various wireless accessories.","marks":[]}]},{"_type":"block","_key":"k320","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k31z","text":"Fitting Assistance: Check My Fit assistance allows you to check if you are wearing your hearing aids correctly. This helps ensure a proper fit for optimal sound quality.","marks":[]}]},{"_type":"block","_key":"k322","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k321","text":"App / Remote Help: ReSound Smart 3D app allows patients to take matters into their own hands by providing quick buttons, custom programs, remote fine-tuning, and tinnitus management. ReSound Assist gives you live Assistance for face-to-face video appointments from the comfort of your home.","marks":[]}]},{"_type":"block","_key":"k324","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k323","text":"Tinnitus Relief: ReSound Relief is one of the most useful hearing aid apps on the market for relieving and managing tinnitus. The app offers a combination of sound therapy, relaxing exercises, meditation, and guidance. The options are endless, as it allows you to layer up to five different sounds to create a soundscape to ease your tinnitus.","marks":[]}]},{"_type":"block","_key":"k326","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k325","text":"Assistive Listening Devices & Technology by ReSound","marks":[]}]},{"_type":"block","_key":"k328","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k327","text":"TV Streamer 2","marks":[]}]},{"_type":"block","_key":"k32a","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k329","text":"Phone Clip","marks":[]}]},{"_type":"block","_key":"k32c","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k32b","text":"Multi Mic","marks":[]}]},{"_type":"block","_key":"k32e","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k32d","text":"Remote Control","marks":[]}]},{"_type":"block","_key":"k32g","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k32f","text":"Older ReSound Hearing Aid Models Supported By New Leaf Hearing Care In Colorado","marks":[]}]},{"_type":"block","_key":"k32i","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k32h","text":"These hearing aid models may still be supported for hearing aid servicing and repair by New Leaf Hearing Care in Arvada, CO and Littleton, CO. Please contact us for more information.","marks":[]}]},{"_type":"block","_key":"k32k","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k32j","text":"ReSound Key","marks":[]}]},{"_type":"block","_key":"k32m","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k32l","text":"ReSound One","marks":[]}]},{"_type":"block","_key":"k32o","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k32n","text":"ReSound Picasso","marks":[]}]},{"_type":"block","_key":"k32q","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k32p","text":"ReSound Enzo Q","marks":[]}]},{"_type":"block","_key":"k32s","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k32r","text":"ReSound LiNX Quattro","marks":[]}]},{"_type":"block","_key":"k32u","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k32t","text":"ReSound LiNX 3D","marks":[]}]},{"_type":"block","_key":"k32w","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k32v","text":"ReSound Enzo 2","marks":[]}]},{"_type":"block","_key":"k32y","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k32x","text":"ReSound LiNX 2","marks":[]}]},{"_type":"block","_key":"k330","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k32z","text":"Frequently Asked Questions About ReSound Hearing Aids","marks":[]}]},{"_type":"block","_key":"k332","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k331","text":"What are the levels of ReSound technology?","marks":[]}]},{"_type":"block","_key":"k334","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k333","text":"The newest ReSound Omnia hearing aids offer 3 technology levels (9, 7, and 5), ranging from the highest to the lowest technology level, respectively.","marks":[]}]},{"_type":"block","_key":"k336","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k335","text":"How do I adjust my ReSound hearing aids?","marks":[]}]},{"_type":"block","_key":"k338","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k337","text":"ReSound hearing aids can be adjusted by pressing the buttons on the hearing aids, or through the ReSound Smart App. Pressing the buttons will allow you to change volume and programs, while the Smart App allows you to make these changes as well as adjustments to sound quality, noise reduction, and much more. Your audiologist or hearing care provider will teach you the best way to adjust your hearing aids for your unique needs.","marks":[]}]},{"_type":"block","_key":"k33a","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k339","text":"What is the life expectancy of ReSound hearing aids?","marks":[]}]},{"_type":"block","_key":"k33c","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k33b","text":"The typical lifespan of a completely new hearing aid is 5 years. Largely, it depends on how well you take care of your hearing aids. Some patients will decide to upgrade their hearing aids prior to this time, as newer technology is routinely released and may provide greater benefits. An audiologist will be able to guide you in deciding when an upgrade is necessary.","marks":[]}]}]', updated_at=datetime('now') WHERE slug='resound-hearing-aids' AND content='[{"_type":"block","_key":"k2z0","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k2yz","text":"ReSound Hearing Aids Available In Colorado","marks":[]}]},{"_type":"block","_key":"k2z2","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2z1","text":"These are the hearing aid models available from ReSound.","marks":[]}]},{"_type":"block","_key":"k2z4","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2z3","text":"ReSound Enzo IA","marks":[]}]},{"_type":"block","_key":"k2z6","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2z5","text":"The ReSound Enzo IA is designed for severe to profound hearing loss. It is the world’s smallest rechargeable Super Power hearing aid and the first of its kind to support Bluetooth LE Audio and Auracast broadcast streaming.","marks":[]}]},{"_type":"block","_key":"k2z8","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2z7","text":"With a stylish, durable design, the ReSound Enzo IA is built for the most challenging listening situations. It offers exceptional clarity, feedback control, and all-day battery life.","marks":[]}]},{"_type":"block","_key":"k2za","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2z9","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k2zc","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2zb","text":"Clear Focus: Automatically reduces background noise while highlighting speech.","marks":[]}]},{"_type":"block","_key":"k2ze","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2zd","text":"360 All-Around listening: Naturally shifts attention between voices and surrounding sounds.","marks":[]}]},{"_type":"block","_key":"k2zg","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2zf","text":"Comfortable and weatherproof: Lightweight, all-day wear with protective nanocoating.","marks":[]}]},{"_type":"block","_key":"k2zi","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2zh","text":"Flexible connectivity: Supports Bluetooth® LE Audio, Auracast™, and direct streaming from multiple devices.","marks":[]}]},{"_type":"block","_key":"k2zk","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2zj","text":"ReSound Vivia","marks":[]}]},{"_type":"block","_key":"k2zm","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2zl","text":"ReSound Vivia™ is a smart hearing aid that helps you hear better and enjoy the sounds around you. It uses Intelligence Augmented (IA), which works with your brain to make hearing easier. Whether you are in a noisy place or a quiet room, ReSound Vivia helps you hear clearly and stay focused on what you want to hear.","marks":[]}]},{"_type":"block","_key":"k2zo","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2zn","text":"ReSound Vivia™ also features advanced noise reduction and speech enhancement, allowing you to focus on conversations even in challenging listening environments. Its adaptive technology continuously adjusts to your surroundings, ensuring a natural and immersive hearing experience. Designed for all-day comfort, ReSound Vivia™ provides reliable performance, so you can stay connected and engaged in every moment without distraction.","marks":[]}]},{"_type":"block","_key":"k2zq","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2zp","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k2zs","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2zr","text":"Bluetooth Connectivity: ReSound Nexia connects to the new Bluetooth LE Audio, providing the purest sound quality and minimal battery usage for continuous streaming.","marks":[]}]},{"_type":"block","_key":"k2zu","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2zt","text":"Auracast Broadcast Audio: A new Bluetooth technology that allows audio streaming from public places to your hearing aids.","marks":[]}]},{"_type":"block","_key":"k2zw","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2zv","text":"App / Remote Help: ReSound Smart 3D app allows patients to take matters into their own hands by providing: quick buttons, custom programs, remote fine-tuning, and tinnitus management. ReSound Assist gives you live Assistance for face-to-face video appointments from the comfort of your home.","marks":[]}]},{"_type":"block","_key":"k2zy","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2zx","text":"ReSound Savi","marks":[]}]},{"_type":"block","_key":"k300","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2zz","text":"ReSound Savi™ is a smart hearing aid that helps you hear clearly and stay connected every day. It combines the best sound technology with small, comfortable designs and easy Bluetooth® connections. ReSound Savi is made to give you natural sound, all-day comfort, and a simple way to hear better in any situation.","marks":[]}]},{"_type":"block","_key":"k302","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k301","text":"ReSound Savi™ automatically adapts to different environments, reducing background noise and enhancing speech clarity so you can focus on the sounds that matter most. Whether you’re in a bustling café, a quiet park, or on an important phone call, its advanced technology ensures a smooth and effortless listening experience. With long-lasting battery life and a user-friendly design, ReSound Savi™ makes hearing easier, keeping you connected and confident throughout your day.","marks":[]}]},{"_type":"block","_key":"k304","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k303","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k306","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k305","text":"All-Day Power: Keeps going all day, even when streaming music or calls.","marks":[]}]},{"_type":"block","_key":"k308","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k307","text":"Weatherproof: Special coating protects the hearing aids from water and dust.","marks":[]}]},{"_type":"block","_key":"k30a","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k309","text":"Bluetooth and Auracast™: Connects to phones, TVs, and other devices with the newest Bluetooth technology.","marks":[]}]},{"_type":"block","_key":"k30c","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k30b","text":"Auracast Assistant: Use the app to easily connect to public broadcasts like in theaters or airports.","marks":[]}]},{"_type":"block","_key":"k30e","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k30d","text":"Hands-Free Calls: Pick up calls with a tap and talk without holding your phone. Works with iPhones, iPads, and some Android phones.","marks":[]}]},{"_type":"block","_key":"k30g","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k30f","text":"ReSound Nexia","marks":[]}]},{"_type":"block","_key":"k30i","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k30h","text":"ReSound Nexia is an advanced hearing system powered by Organic Hearing™, providing a natural sound experience and seamless connectivity. With ReSound Nexia, users can stream hands-free calls from iPhone, iPad, and compatible Android™ devices directly to their hearing aids. Additionally, these hearing aids can function as a headset, allowing users to stream audio from Mac computers for online meetings or FaceTime calls.","marks":[]}]},{"_type":"block","_key":"k30k","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k30j","text":"For individuals with single-sided deafness, ReSound Nexia offers a wireless ‘CROS’ solution, delivering full sound clarity and matching the microRIE style for a comfortable fit. This comprehensive system enhances daily life by providing clear and natural sound quality, effortless connectivity, and personalized solutions for users with varying hearing needs.","marks":[]}]},{"_type":"block","_key":"k30m","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k30l","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k30o","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k30n","text":"Bluetooth Connectivity: ReSound Nexia connects to the new Bluetooth LE Audio, providing the purest sound quality and minimal battery usage for continuous streaming.","marks":[]}]},{"_type":"block","_key":"k30q","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k30p","text":"Auracast Broadcast Audio: A new Bluetooth technology that allows audio streaming from public places to your hearing aids.","marks":[]}]},{"_type":"block","_key":"k30s","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k30r","text":"App / Remote Help: ReSound Smart 3D app allows patients to take matters into their own hands by providing quick buttons, custom programs, remote fine-tuning, and tinnitus management. ReSound Assist gives you live Assistance for face-to-face video appointments from the comfort of your home.","marks":[]}]},{"_type":"block","_key":"k30u","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k30t","text":"ReSound Omnia RIE & mini RIE","marks":[]}]},{"_type":"block","_key":"k30w","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k30v","text":"ReSound’s newest Omnia hearing aid products operate on the foundation of their Organic Hearing technology. The core principles behind Organic Hearing include natural sound, natural fit, and natural connection to the world. ReSound crafted the perfect balance of nature and science in designing hearing solutions meant to fit your life organically.","marks":[]}]},{"_type":"block","_key":"k30y","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k30x","text":"ReSound Omnia receiver-in-the-ear (RIE) is currently available in two styles: a RIE or mini RIE. These devices are appropriate for fitting mild-to-severe hearing losses. They offer either rechargeable or disposable battery options. Their rechargeable solutions have proven to provide all-day battery power on one charge – even when streaming 100% of the time. This gives you confidence that your hearing aids will perform when you need them.","marks":[]}]},{"_type":"block","_key":"k310","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k30z","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k312","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k311","text":"Bluetooth Connectivity: ReSound OMNIA is made for iPhone and iPad and works with Android devices. Stream hands-free calls for iPhone and iPad. You can also connect to various wireless accessories.","marks":[]}]},{"_type":"block","_key":"k314","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k313","text":"Fitting Assistance: Check My Fit assistance allows you to check if you are wearing your hearing aids correctly. This helps ensure a proper fit for optimal sound quality.","marks":[]}]},{"_type":"block","_key":"k316","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k315","text":"App / Remote Help: ReSound Smart 3D app allows patients to take matters into their own hands by providing quick buttons, custom programs, remote fine-tuning, and tinnitus management. ReSound Assist gives you live Assistance for face-to-face video appointments from the comfort of your home.","marks":[]}]},{"_type":"block","_key":"k318","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k317","text":"Tinnitus Relief: ReSound Relief is one of the most useful hearing aid apps on the market for relieving and managing tinnitus. The app offers a combination of sound therapy, relaxing exercises, meditation, and guidance. The options are endless, as it allows you to layer up to five different sounds to create a soundscape to ease your tinnitus.","marks":[]}]},{"_type":"block","_key":"k31a","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k319","text":"ReSound Omnia ITE","marks":[]}]},{"_type":"block","_key":"k31c","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k31b","text":"ReSound’s Omnia family of hearing aids also offers custom in-the-ear (ITE) devices that are designed to fit your unique ear anatomy. This allows you to enjoy all the benefits of modern hearing aid technology in a smaller package. One of the benefits of choosing a custom device is that it is naturally shielded from wind noise, as they sit inside the ear canal. Additionally, ITE devices do not interfere with glasses or other items worn behind the ears.","marks":[]}]},{"_type":"block","_key":"k31e","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k31d","text":"ReSound Omnia in-the-ear (ITE) products are currently available in a variety of sizes to meet your unique fitting preferences. The types of custom ITE products include: in-the-canal (ITC), completely-in-the-canal (CIC), and invisible-in-the-canal (IIC). These devices are appropriate for fitting mild to severe-to-profound hearing losses. They offer either rechargeable or disposable battery options.","marks":[]}]},{"_type":"block","_key":"k31g","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k31f","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k31i","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k31h","text":"Bluetooth Connectivity: ReSound OMNIA is made for iPhone and iPad and works with Android devices. Stream hands-free calls for iPhone and iPad. You can also connect to various wireless accessories.","marks":[]}]},{"_type":"block","_key":"k31k","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k31j","text":"Fitting Assistance: Check My Fit assistance allows you to check if you are wearing your hearing aids correctly. This helps ensure a proper fit for optimal sound quality.","marks":[]}]},{"_type":"block","_key":"k31m","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k31l","text":"App / Remote Help: ReSound Smart 3D app allows patients to take matters into their own hands by providing quick buttons, custom programs, remote fine-tuning, and tinnitus management. ReSound Assist gives you live Assistance for face-to-face video appointments from the comfort of your home.","marks":[]}]},{"_type":"block","_key":"k31o","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k31n","text":"Tinnitus Relief: ReSound Relief is one of the most useful hearing aid apps on the market for relieving and managing tinnitus. The app offers a combination of sound therapy, relaxing exercises, meditation, and guidance. The options are endless, as it allows you to layer up to five different sounds to create a soundscape to ease your tinnitus.","marks":[]}]},{"_type":"block","_key":"k31q","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k31p","text":"ReSound Omnia BTE & Power BTE","marks":[]}]},{"_type":"block","_key":"k31s","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k31r","text":"The traditional behind-the-ear (BTE) style is also available in the Omnia family. For individuals with significant hearing loss, listening to noise can be extremely difficult. Thankfully, ReSound OMNIA offers the only beamforming in the industry to improve hearing in noise without feeling like volume is compromised.  Their studies revealed that this translated into an incredible 150% improvement in speech understanding of noise.","marks":[]}]},{"_type":"block","_key":"k31u","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k31t","text":"ReSound Omnia BTE and Power BTE are currently available in a BTE style. These devices are appropriate for fitting mild to severe-to-profound hearing losses. They both offer a rechargeable battery solution.","marks":[]}]},{"_type":"block","_key":"k31w","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k31v","text":"Unique Perks and Features:","marks":[]}]},{"_type":"block","_key":"k31y","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k31x","text":"Bluetooth Connectivity: ReSound OMNIA is made for iPhone and iPad and works with Android devices. Stream hands-free calls for iPhone and iPad. You can also connect to various wireless accessories.","marks":[]}]},{"_type":"block","_key":"k320","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k31z","text":"Fitting Assistance: Check My Fit assistance allows you to check if you are wearing your hearing aids correctly. This helps ensure a proper fit for optimal sound quality.","marks":[]}]},{"_type":"block","_key":"k322","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k321","text":"App / Remote Help: ReSound Smart 3D app allows patients to take matters into their own hands by providing quick buttons, custom programs, remote fine-tuning, and tinnitus management. ReSound Assist gives you live Assistance for face-to-face video appointments from the comfort of your home.","marks":[]}]},{"_type":"block","_key":"k324","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k323","text":"Tinnitus Relief: ReSound Relief is one of the most useful hearing aid apps on the market for relieving and managing tinnitus. The app offers a combination of sound therapy, relaxing exercises, meditation, and guidance. The options are endless, as it allows you to layer up to five different sounds to create a soundscape to ease your tinnitus.","marks":[]}]},{"_type":"block","_key":"k326","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k325","text":"Assistive Listening Devices & Technology by ReSound","marks":[]}]},{"_type":"block","_key":"k328","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k327","text":"TV Streamer 2","marks":[]}]},{"_type":"block","_key":"k32a","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k329","text":"Phone Clip","marks":[]}]},{"_type":"block","_key":"k32c","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k32b","text":"Multi Mic","marks":[]}]},{"_type":"block","_key":"k32e","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k32d","text":"Remote Control","marks":[]}]},{"_type":"block","_key":"k32g","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k32f","text":"Older ReSound Hearing Aid Models Supported By New Leaf Hearing Care In Colorado","marks":[]}]},{"_type":"block","_key":"k32i","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k32h","text":"These hearing aid models may still be supported for hearing aid servicing and repair by New Leaf Hearing Care in Arvada, CO and Littleton, CO. Please contact us for more information.","marks":[]}]},{"_type":"block","_key":"k32k","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k32j","text":"ReSound Key","marks":[]}]},{"_type":"block","_key":"k32m","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k32l","text":"ReSound One","marks":[]}]},{"_type":"block","_key":"k32o","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k32n","text":"ReSound Picasso","marks":[]}]},{"_type":"block","_key":"k32q","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k32p","text":"ReSound Enzo Q","marks":[]}]},{"_type":"block","_key":"k32s","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k32r","text":"ReSound LiNX Quattro","marks":[]}]},{"_type":"block","_key":"k32u","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k32t","text":"ReSound LiNX 3D","marks":[]}]},{"_type":"block","_key":"k32w","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k32v","text":"ReSound Enzo 2","marks":[]}]},{"_type":"block","_key":"k32y","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k32x","text":"ReSound LiNX 2","marks":[]}]},{"_type":"block","_key":"k330","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k32z","text":"Frequently Asked Questions About ReSound Hearing Aids","marks":[]}]},{"_type":"block","_key":"k332","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k331","text":"What are the levels of ReSound technology?","marks":[]}]},{"_type":"block","_key":"k334","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k333","text":"The newest ReSound Omnia hearing aids offer 3 technology levels (9, 7, and 5), ranging from the highest to the lowest technology level, respectively.","marks":[]}]},{"_type":"block","_key":"k336","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k335","text":"How do I adjust my ReSound hearing aids?","marks":[]}]},{"_type":"block","_key":"k338","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k337","text":"ReSound hearing aids can be adjusted by pressing the buttons on the hearing aids, or through the ReSound Smart App. Pressing the buttons will allow you to change volume and programs, while the Smart App allows you to make these changes as well as adjustments to sound quality, noise reduction, and much more. Your audiologist or hearing care provider will teach you the best way to adjust your hearing aids for your unique needs.","marks":[]}]},{"_type":"block","_key":"k33a","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k339","text":"What is the life expectancy of ReSound hearing aids?","marks":[]}]},{"_type":"block","_key":"k33c","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k33b","text":"The typical lifespan of a completely new hearing aid is 5 years. Largely, it depends on how well you take care of your hearing aids. Some patients will decide to upgrade their hearing aids prior to this time, as newer technology is routinely released and may provide greater benefits. An audiologist will be able to guide you in deciding when an upgrade is necessary.","marks":[]}]}]';
